contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address _target, uint _value) public payable {
        require(_value <= address(c).balance);
        require(_target != address(c));
        uint beforeBalance = address(c).balance;
        bool reverted;
        c.sendMoney(_target, _value, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterBalance = address(c).balance;
        assert(reverted || afterBalance == beforeBalance - _value);
    }
    receive() external payable {}
}

